import { describe, expect, it } from "vitest";
import { WORLD } from "./fixture";
import { offTopic, quickScreen } from "./quick";

const q = (t: string) => quickScreen(t, WORLD);

describe("the fast lane leaves reasoning to the planner", () => {
  it("multi-intent, mission and advice sentences do not run as a plain screen", () => {
    expect(q("prepare for heavy rain")).toBeNull();
    expect(q("We expect heavy rain tonight, get everything ready")).toBeNull();
    expect(q("show the severe cases and then open the first one")).toBeNull();
    expect(q("compare the rain in Adyar and Perungudi")).toMatchObject({ recipe: "compare", slots: { zones: [13, 14] } });
    expect(q("what should I do about flooding in Adyar")).toMatchObject({ recipe: "advise", slots: { zones: [13], cat: "FLOOD_WATERLOGGING" } });
    expect(q("என்ன செய்யலாம் வெள்ளம் அடையாறு")).toMatchObject({ recipe: "advise" });
  });
  it("new recipes by rules: what stands out, complete this data, performance, ranking, nearby", () => {
    expect(q("what stands out this week")).toMatchObject({ recipe: "insight" });
    expect(q("any anomalies in Adyar")).toMatchObject({ recipe: "insight", slots: { zones: [13] } });
    expect(q("fill in the missing data")).toMatchObject({ recipe: "complete" });
    expect(q("complete this data")).toMatchObject({ recipe: "complete" });
    expect(q("show the unresolved incidents, fill what you can")).toMatchObject({ recipe: "complete" });
    expect(q("department-wise performance")).toMatchObject({ recipe: "performance", slots: { by: "dept" } });
    expect(q("worst zones this week")).toMatchObject({ recipe: "ranking" });
    expect(q("schools within 1 km of flooding in Adyar")).toMatchObject({ recipe: "nearby" });
    expect(q("make me a flooding dashboard for this week")).toMatchObject({ recipe: "dashboard" });
  });
  it("a Tamil place with a case ending, and a spelling the lexicon does not list", () => {
    expect(q("அடையாறில் கடுமையான சம்பவங்கள்")).toMatchObject({ recipe: "cases", slots: { zones: [13] } });
    expect(q("அம்பத்தூரில் புகார்கள் இந்த வாரம்")).toMatchObject({ slots: { zones: [7] } });
  });
});

describe("the fast lane hands off when it is unsure", () => {
  it.each([
    ["one word of the sentence looks like a price", "Show me the police closure rates by zone"],
    ["a topic named, with no request for its cases", "What is the freezing point of heavy water?"],
    ["more of the sentence unknown than known", "Metro Water pipeline leakage inspection audit backlog"],
    ["a map word it cannot fill", "Show the GIS overlay of broken streetlights in Manali"],
    ["near something that is not a facility", "water stagnation spots near the Guindy flyover"],
    ["asked to keep the view", "Pin this water level view as Monsoon Monitor"],
    ["two kinds of question", "morning briefing on rain"],
    ["two topics", "rain and air quality in Adyar"],
    ["a comparison with one zone named", "Put Puzhal and Poondi side by side"],
    ["how a topic is doing", "how is dengue doing in Kodambakkam"],
    ["Tanglish it cannot account for", "Teynampet la kuppai yaarum eduthuttu pogave illa romba naala"],
    ["Tamil it cannot account for", "போன மாசம் டெங்கு கொஞ்சம் கூடிக்கிட்டே வந்துச்சு போல"]
  ])("%s", (_, t) => expect(q(t)).toBeNull());
  it("keeps what it is sure of", () => {
    expect(q("Why did garbage complaints spike in Manali")).toMatchObject({ recipe: "why", slots: { zones: [2], cat: "SOLID_WASTE" } });
    expect(q("பூண்டி டேம் நிலவரம்")).toMatchObject({ recipe: "readings", slots: { metric: "lakes", name: "Poondi" } });
    expect(q("how full is Chembarambakkam")).toMatchObject({ recipe: "readings", slots: { metric: "lakes", name: "Chembarambakkam" } });
    expect(q("tomato rate at Koyambedu")).toMatchObject({ recipe: "prices" });
    expect(q("any garbage complaints in Adyar")).toMatchObject({ recipe: "cases", slots: { zones: [13] } });
    expect(q("அடையாறில் புகார்கள் காட்டு")).toMatchObject({ recipe: "cases", slots: { zones: [13] } });
    expect(q("Adyar la complaints kaattu")).toMatchObject({ recipe: "cases", slots: { zones: [13] } });
  });
  it("still gives its reading to the frame, which asks with noBail", () => {
    expect(quickScreen("Pin this water level view", WORLD, { noBail: true })).not.toBeNull();
  });
});

describe("Jarvis's fast lane: everyday questions answered from the data with no model", () => {
  it("severe cases, in a place, in a period", () => {
    expect(q("Show me the severe cases")).toMatchObject({ recipe: "cases", slots: { sev: "Severe", period: "daily" } });
    expect(q("severe cases in Adyar this week")).toMatchObject({ recipe: "cases", slots: { sev: "Severe", zones: [13], period: "weekly" } });
    expect(q("இன்று கடுமையான சம்பவங்கள் என்ன?")).toMatchObject({ recipe: "cases", slots: { sev: "Severe", period: "daily" } });
  });
  it("a place's news is filtered to that place", () => {
    expect(q("Latest news in Adyar")).toMatchObject({ recipe: "news", slots: { zones: [13] } });
    expect(q("What is the news in Anna Nagar today?")).toMatchObject({ recipe: "news", slots: { zones: [8], period: "daily" } });
    expect(q("அடையாறு செய்திகள் காட்டு")).toMatchObject({ recipe: "news", slots: { zones: [13] } });
    expect(q("today's news")).toMatchObject({ recipe: "news", slots: { zones: [] } });
  });
  it("prices, in English, Tamil and Tanglish", () => {
    expect(q("What is the price of tomato today?")).toMatchObject({ recipe: "prices", slots: { q: "tomato" } });
    expect(q("தக்காளி விலை என்ன?")).toMatchObject({ recipe: "prices", slots: { q: "தக்காளி" } });
    expect(q("thakkali vilai enna")).toMatchObject({ recipe: "prices" });
    expect(q("vegetable prices")).toMatchObject({ recipe: "prices", slots: { q: null } });
  });
  it("air, rain and the reservoirs", () => {
    expect(q("How is the air quality in Manali?")).toMatchObject({ recipe: "readings", slots: { metric: "aqi", zones: [2] } });
    expect(q("How full are the reservoirs?")).toMatchObject({ recipe: "readings", slots: { metric: "lakes" } });
    expect(q("how much rain today")).toMatchObject({ recipe: "readings", slots: { metric: "rain" } });
  });
  it("why, where and compare", () => {
    expect(q("Why are there so many flooding complaints in Royapuram?")).toMatchObject({ recipe: "why", slots: { zones: [5], cat: "FLOOD_WATERLOGGING" } });
    expect(q("Where did the fire accident happen today?")).toMatchObject({ recipe: "cases", slots: { cat: "FIRE_EXPLOSION", period: "daily" } });
    expect(q("compare Adyar and Ambattur this week")).toMatchObject({ recipe: "compare", slots: { zones: [13, 7] } });
  });
  it("leaves follow-ups and commands to the agent", () => {
    for (const t of ["same for Anna Nagar", "only the severe ones", "open the third one", "draft a message for the first case", "go to trends"]) expect(q(t)).toBeNull();
  });
});

describe("Jarvis keeps to the district", () => {
  it.each(["What is deep learning?", "who is the president of America", "tell me a joke", "write a poem about the sea", "explain machine learning", "டீப் லேர்னிங் என்றால் என்ன?"])(
    "declines %j", (t) => expect(offTopic(t, WORLD)).toBe(true));
  it.each(["What is the price of tomato today?", "what is happening in Adyar", "what are the severe cases", "explain why flooding is rising in Royapuram",
    "who is the officer for storm water drains", "அடையாறு செய்திகள் காட்டு", "Show me the severe cases", "hello"])(
    "answers %j", (t) => expect(offTopic(t, WORLD)).toBe(false));
});

